15	 */
16	@RestControllerAdvice
17	public class GlobalExceptionHandler {
18	
19	    @ExceptionHandler(BatchRejectedException.class)
20	    public ResponseEntity<ErrorResponse> handleBatchRejected(BatchRejectedException ex) {
21	        return ResponseEntity.status(ex.getStatus())
22	                .body(new ErrorResponse(ex.getCode(), ex.getMessage(), ex.getFailures()));
23	    }
