26	    public ResponseEntity<ErrorResponse> handleApi(ApiException ex) {
27	        return ResponseEntity.status(ex.getStatus())
28	                .body(new ErrorResponse(ex.getCode(), ex.getMessage()));
29	    }
30	
31	    @ExceptionHandler({
32	            HttpMessageNotReadableException.class,
33	            MissingRequestHeaderException.class,
34	            MissingServletRequestParameterException.class,
35	            MethodArgumentTypeMismatchException.class,
36	            IllegalArgumentException.class
37	    })
38	    public ResponseEntity<ErrorResponse> handleBadRequest(Exception ex) {
39	        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
40	                .body(new ErrorResponse("BAD_REQUEST", "请求参数非法: " + ex.getMessage()));
41	    }
42	
43	    @ExceptionHandler(NoResourceFoundException.class)
44	    public ResponseEntity<ErrorResponse> handleNotFound(NoResourceFoundException ex) {
45	        return ResponseEntity.status(HttpStatus.NOT_FOUND)
46	                .body(new ErrorResponse("NOT_FOUND", "资源不存在"));
47	    }
48	
49	    @ExceptionHandler(Exception.class)
